(()=>{const K='rc_pending_trial_v1';try{const p=JSON.parse(sessionStorage.getItem(K)||'null'),hasToken=new URLSearchParams(location.hash.slice(1)).has('access_token');if(!p||!hasToken)return;location.hash='#dj-login';const notify=()=>{const b=[...document.querySelectorAll('button')].find(x=>/generar.*código|generar código/i.test(x.textContent||''));if(b){b.click();setTimeout(()=>{const n=document.createElement('div');n.textContent='Correo verificado. Tu código de acceso DJ fue generado automáticamente.';n.style='position:fixed;z-index:9999;top:16px;left:16px;right:16px;padding:14px;border:1px solid #27f5d2;background:#071b1b;color:#72ffe5;border-radius:14px;text-align:center;font:600 14px system-ui';document.body.appendChild(n);setTimeout(()=>n.remove(),9000)},1200)}else setTimeout(notify,300)};setTimeout(notify,1200)}catch(e){}})();
